head.script:

	scwin.onpageload = function() {
		var jsonData = [{col1:"한글테스트가나다러", col2:"test1"}
						,{col1:"가나더라", col2:"aaa"}
						,{col1:"웹스퀘어1", col2:"abc"}
						,{col1:"웹스퀘어2", col2:"TEST2"}
						,{col1:"ABD", col2:"ABD"}];
		dataList1.setJSON(jsonData);
	};

	scwin.onpageunload = function() {

	};

    scwin.autoComplete1_onafteredit = function(info){
        //debugger;
        //alert("info");
	window.info="info";

    }

	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView2_button_0_9', 'key-combo', {
			combo: 'TAB'
		});
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#autoComplete1_input', 'key-sequence', {
			sequence: 'A'
		});
	}	
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}

	scwin.checkVal = function() {
		return window.info == "info";
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_input').focus()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_itemTable_option2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
